UNION ALL SELECT 'TSR', 'USXC', 'CJAACDGO,PJRQCDUS,USXCCDGO,USXCESTD,USXCFCDS,USXCFCIN,USXCNMBR' FROM DUAL
),
COLS AS (
    SELECT E.OWNER_ESP,
           E.TABLA_ESP,
           TRIM(REGEXP_SUBSTR(E.COLS, '[^,]+', 1, L.LVL)) AS COLUMNA_ESP
    FROM   ESPERADO E
           CROSS JOIN (SELECT LEVEL AS LVL FROM DUAL CONNECT BY LEVEL <= 60) L
    WHERE  REGEXP_SUBSTR(E.COLS, '[^,]+', 1, L.LVL) IS NOT NULL
)
-- ============================================================================
-- CONSULTA A - Tablas mapeadas por una entidad que NO existen en la base.
-- Esperado: 0 filas.
-- ============================================================================
SELECT DISTINCT 'A. TABLA INEXISTENTE' AS HALLAZGO,
       C.OWNER_ESP || '.' || C.TABLA_ESP AS OBJETO,
       NULL AS COLUMNA
FROM   COLS C
WHERE  NOT EXISTS (SELECT 1 FROM ALL_TAB_COLUMNS A
                   WHERE A.OWNER = C.OWNER_ESP AND A.TABLE_NAME = C.TABLA_ESP)

UNION ALL

-- ============================================================================
-- CONSULTA B - Columnas mapeadas que faltan, en tablas que SI existen.
-- Cada fila es un ORA-00904 esperando el despliegue. Esperado: 0 filas.
-- ============================================================================
SELECT 'B. COLUMNA FALTANTE',
       C.OWNER_ESP || '.' || C.TABLA_ESP,
       C.COLUMNA_ESP
FROM   COLS C
WHERE  EXISTS     (SELECT 1 FROM ALL_TAB_COLUMNS A
                   WHERE A.OWNER = C.OWNER_ESP AND A.TABLE_NAME = C.TABLA_ESP)
AND    NOT EXISTS (SELECT 1 FROM ALL_TAB_COLUMNS A
                   WHERE A.OWNER = C.OWNER_ESP AND A.TABLE_NAME = C.TABLA_ESP
                   AND   A.COLUMN_NAME = C.COLUMNA_ESP)

ORDER BY 1, 2, 3;
